import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    names, xs, ys = [], [], []
    p = 1
    for _ in range(n):
        names.append(data[p]); xs.append(int(data[p + 1])); ys.append(int(data[p + 2]))
        p += 3
    best = {}
    for key, other in ((xs, ys), (ys, xs)):
        groups = defaultdict(list)
        for i in range(n):
            groups[key[i]].append(i)
        for g in groups.values():
            g.sort(key=lambda i: other[i])
            for t, i in enumerate(g):
                for u in (t - 1, t + 1):
                    if 0 <= u < len(g):
                        j = g[u]
                        cand = (abs(other[i] - other[j]), names[j])
                        if names[i] not in best or cand < best[names[i]]:
                            best[names[i]] = cand
    m = int(data[p])
    out = []
    for q in data[p + 1:p + 1 + m]:
        out.append(best[q][1] if q in best else 'NONE')
    print('\n'.join(out))

main()

