data = sys.stdin.read().split()
n = int(data[0])
cities = []
p = 1
for _ in range(n):
    cities.append((data[p], int(data[p + 1]), int(data[p + 2])))
    p += 3
m = int(data[p])
out = []
for q in data[p + 1:p + 1 + m]:
    qx = qy = None
    for nm, x, y in cities:
        if nm == q:
            qx, qy = x, y
    best = None
    for nm, x, y in cities:
        if nm == q:
            continue
        if x == qx or y == qy:
            cand = (abs(x - qx) + abs(y - qy), nm)
            if best is None or cand < best:
                best = cand
    out.append(best[1] if best else 'NONE')
print('\n'.join(out))

